//! French user documentation of the registry (`vskubuno/docs/DESIGNER.md` section 11): the same
//! short, user-facing sentences as each component's, property's and event's English `doc`, shown
//! by Visual Studio's Properties window and Toolbox when Visual Studio runs in French. Keyed like
//! [`key`]: `"Button"` for a component, `"Button.Text"` for a property or an event. Keep in step
//! with the English `doc` strings (a test checks every registry member has an entry).

/// The key of a component (`member` = `None`) or of one of its properties/events.
pub fn key(component: &str, member: Option<&str>) -> String {
    match member {
        Some(m) => format!("{component}.{m}"),
        None => component.to_string(),
    }
}

/// The French documentation of `component`'s property `property`: the component's own entry, else
/// the entry of the level it inherits it from (`Control.BackColor`, `View.Title`…).
pub fn property_french(component: &str, property: &str, level: Option<&str>) -> Option<&'static str> {
    french(&key(component, Some(property)))
        .or_else(|| french(&key(level?, Some(property))))
        // The icon options every element with an icon takes (`common::ICON_OPTION_PROPERTIES`).
        .or_else(|| super::common::ICON_OPTION_PROPERTIES.iter().any(|p| p.name == property).then(|| french(&key("Icon", Some(property)))).flatten())
}

