/// The French documentation of `component`'s event `event`: the component's own entry,
/// else the common one (`*.<event>`), else the view event's (`View.<event>`).
pub fn event_french(component: &str, event: &str) -> Option<&'static str> {
    french(&key(component, Some(event))).or_else(|| french(&key("*", Some(event)))).or_else(|| french(&key("View", Some(event))))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every registered component, property and event has its French documentation, and every English
    /// `doc` reads as user text (no code or implementation vocabulary - those go in code comments).
    #[test]
    fn every_registry_member_is_documented_for_users_in_both_languages() {
        for meta in crate::registry::builtins() {
            let mut members: Vec<(Option<&str>, &str)> = vec![(None, meta.doc)];
            members.extend(meta.properties.iter().map(|p| (Some(p.name), p.doc)));
            members.extend(meta.events.iter().map(|e| (Some(e.name), e.doc)));
            for (member, doc) in members {
                let k = key(meta.name, member);
                assert!(french(&k).is_some(), "no French doc for {k}");
                for word in ["`", "replica", "::", "crate", "module doc"] {
                    assert!(
                        !doc.contains(word),
                        "{k}'s doc is not user text ({word:?}): {doc}"
                    );
                }
            }
        }
    }

    /// The properties every control inherits (and the view's) are documented in both languages, in user
    /// words, whatever element inherits them.
    #[test]
    fn inherited_and_view_properties_are_documented_for_users_in_both_languages() {
        for meta in crate::registry::builtins() {
            for (level, p) in meta.all_properties() {
                assert!(property_french(meta.name, p.name, level).is_some(), "no French doc for {}.{} ({level:?})", meta.name, p.name);
            }
        }
        let levels = crate::registry::LEVELS.iter().flat_map(|l| l.properties.iter().map(move |p| (l.name, p)));
        for (level, p) in levels {
            assert!(french(&key(level, Some(p.name))).is_some(), "no French doc for {level}.{}", p.name);
            for word in ["`", "replica", "::", "crate", "module doc"] {
                assert!(!p.doc.contains(word), "{level}.{}'s doc is not user text ({word:?}): {}", p.name, p.doc);
            }
        }
    }

    #[test]
    fn common_and_view_events_are_documented_in_french() {
        for e in super::super::COMMON_EVENTS {
            assert!(french(&key("*", Some(e.name))).is_some(), "no French doc for *.{}", e.name);
        }
        for e in super::super::VIEW_EVENTS {
            assert!(french(&key("View", Some(e.name))).is_some(), "no French doc for View.{}", e.name);
        }
        for meta in crate::registry::builtins() {
            for e in meta.all_events() {
                assert!(event_french(meta.name, e.name).is_some(), "{}.{}", meta.name, e.name);
            }
        }
    }
}
